import{_ as t,o as a,c as _,a4 as r}from"./chunks/framework.CZTQpGgQ.js";const i=JSON.parse('{"title":"小小蓝莓果 解锁曲靖师宗智慧农业新图景","description":"","frontmatter":{"sidebar":false,"aside":false,"editLink":false,"lastUpdated":false,"prev":false,"next":false,"title":"小小蓝莓果 解锁曲靖师宗智慧农业新图景","date":"2026-11-28T00:00:00.000Z","source":"农业农村部智慧农业专题","category":"news","link":"https://www.moa.gov.cn/ztzl/zhnyzxd/xydt/202611/t20261127_6489817.htm","summary":"初冬时节,走进云南省曲靖市师宗县竹基镇界桥村现代化蓝莓种植基地,一排排高标准温室大棚在阳光下整齐排列。大棚里生机盎然:翠绿的蓝莓枝叶繁茂,枝叶间垂挂着一簇簇清甜饱满的果实,表面覆着一层薄薄的天然白霜,长势格外喜人。\\n师宗县竹基镇界桥村现代化蓝莓种植基地。\\n“我们采用的是无土栽培和水肥一体化的蓝莓种植模式,对比传统地栽蓝莓有几个优势。...\\n","contentHash":"475facb990c24eb12f28166818686c92","tags":["智慧农业","行业资讯"]},"headers":[],"relativePath":"news/2026-11-28-小小蓝莓果-解锁曲靖师宗智慧农业新图景.md","filePath":"news/2026-11-28-小小蓝莓果-解锁曲靖师宗智慧农业新图景.md"}'),p={name:"news/2026-11-28-小小蓝莓果-解锁曲靖师宗智慧农业新图景.md"};function n(s,e,o,l,c,d){return a(),_("div",null,[...e[0]||(e[0]=[r('<h1 id="小小蓝莓果-解锁曲靖师宗智慧农业新图景" tabindex="-1">小小蓝莓果 解锁曲靖师宗智慧农业新图景 <a class="header-anchor" href="#小小蓝莓果-解锁曲靖师宗智慧农业新图景" aria-label="Permalink to &quot;小小蓝莓果 解锁曲靖师宗智慧农业新图景&quot;">​</a></h1><blockquote><p>来源: <a href="https://www.moa.gov.cn/ztzl/zhnyzxd/xydt/202611/t20261127_6489817.htm" target="_blank" rel="noreferrer">农业农村部智慧农业专题</a><br> 日期: 2026-11-28 摘要: 初冬时节,走进云南省曲靖市师宗县竹基镇界桥村现代化蓝莓种植基地,一排排高标准温室大棚在阳光下整齐排列。大棚里生机盎然:翠绿的蓝莓枝叶繁茂,枝叶间垂挂着一簇簇清甜饱满的果实,表面覆着一层薄薄的天然白霜,长势格外喜人。 师宗县竹基镇界桥村现代化蓝莓种植基地。 “我们采用的是无土栽培和水肥一体化的蓝莓种植模式,对比传统地栽蓝莓有几个优势。...</p></blockquote><p>师宗县竹基镇界桥村现代化蓝莓种植基地。</p><p>“我们采用的是无土栽培和水肥一体化的蓝莓种植模式,对比传统地栽蓝莓有几个优势。”基地负责人刘翔指着大棚内的智能控制设备介绍,“在水肥上,可以精准控制,达到比较理想的水肥环境;同时病虫害风险降低,农药施用大幅减少,挂果率显著提升,果品品质大幅改善。”</p><p>眼下蓝莓进入盛果期,工人们在繁茂的枝叶间熟练地翻找,指尖轻轻一捻,伴随着清脆的“吧嗒”声,一颗颗圆润饱满的蓝莓便落入采摘篓中。“今年是我们第一年试种,还算养苗阶段,每盆的挂果量1公斤左右,到明年我们可以实现每盆增产4公斤。”刘翔对明年的丰产充满信心。</p><p>采摘下来的蓝莓在最短时间进入包装车间。在明亮的灯光下,分拣线平稳运转,工人们快速而细致地将传送带上的蓝莓称重、分级,将优质的精品果整齐地码放进印有标志的包装盒中,随后通过全程冷链,当日发车,6小时内发往全国各大城市的大型商超,甚至远销东南亚国家。</p><p>工人们采摘蓝莓。</p><p>随着产业链的不断完善,基地的联农带农效应日益凸显。刘翔介绍:“目前我们种植面积300余亩,采收、包装、分拣全流程都需要人工操作,用工量每天都在200多人。”在彩云镇千亩蓝莓基地里,蓝莓同样迎来了丰收季。</p><p>智能化的蓝莓工厂创造了800余个“科技农人”岗位,村民通过专业培训掌握疏果、智能分拣等技能,年劳务收入超过1000万元。大棚里,小乃邑村民昝乔生正在忙碌:“我们老两口来这里很近,在基地务工两年多了,两个人一天挣得到300多块。不用风吹日晒,很轻松,有干劲。”冬日里田间地头的繁忙景象,正是师宗县以科技赋能蓝莓产业高质量发展的生动注脚。</p><p>包装车间内工人们快速而细致地将传送带上的蓝莓称重、分级。</p><p>近年来,师宗县因地制宜,构建起以彩云镇为核心,竹基镇、丹凤街道、漾月街道为辐射的“一核三区”产业布局。目前,全县蓝莓种植总面积达2666亩,设施化率高达95.3%,年产量约2045吨,产值突破1.02亿元。通过全面推广大棚基质栽培、水肥一体化灌溉和物联网智能监控,传统种植正加速向智慧农业转型。</p><p>依托“企业+基地+农户”的模式,这颗小小的蓝莓果,正带动越来越多群众在乡村振兴的道路上稳步前行。(卢俊欣、窦盛根、冯继扬 文/图)</p><p>来源:师宗县融媒体中心</p><p><a href="https://www.moa.gov.cn/ztzl/zhnyzxd/xydt/202611/t20261127_6489817.htm" target="_blank" rel="noreferrer">阅读原文</a></p>',14)])])}const h=t(p,[["render",n]]);export{i as __pageData,h as default};
